/* empty css                                                                               */import{H as e}from"./chunks/HighLightText.D0qzB827.js";import{c as r,o as t,a as s,b as p,d as l,e as a,w as i}from"./chunks/vitepress-theme-teek.VWKGyrHm.js";/* empty css                                                             */const h=JSON.parse('{"title":"Context Engineering：上下文工程","description":"阐述 Prompt Engineering 到 Context Engineering 的范式演进：从单次指令到为 LLM 构建包含 RAG 知识库、对话记忆、工具调用能力的持久认知环境，涵盖上下文窗口管理、长文本处理策略与多轮对话状态维护等工程实践。","frontmatter":{"title":"Context Engineering：上下文工程","tldr":"从 Prompt 到 Context——通过 RAG、记忆与工具调用，为 LLM 构建持久认知环境而非一次性指令。","description":"阐述 Prompt Engineering 到 Context Engineering 的范式演进：从单次指令到为 LLM 构建包含 RAG 知识库、对话记忆、工具调用能力的持久认知环境，涵盖上下文窗口管理、长文本处理策略与多轮对话状态维护等工程实践。","tags":["概念","上下文工程","RAG","Function Calling"],"categories":["大模型基础","推理与生成"],"date":"2026-06-29T09:51:10.000Z","permalink":"/llm-basic/context-engineering"},"headers":[],"relativePath":"llm-basic/context-engineering.md","filePath":"22.大模型基础/04.推理与生成/03.Context-Engineering.md"}'),b={name:"llm-basic/context-engineering.md"},k=Object.assign(b,{setup(c){return(o,n)=>(t(),r("div",null,[n[7]||(n[7]=s("h1",{id:"context-engineering-上下文工程",tabindex:"-1"},[a("Context Engineering：上下文工程 "),s("a",{class:"header-anchor",href:"#context-engineering-上下文工程","aria-label":"Permalink to “Context Engineering：上下文工程”"},"​")],-1)),n[8]||(n[8]=s("blockquote",null,[s("p",null,[s("strong",null,"摘要"),a(": Context Engineering 是 Prompt Engineering 的自然演进——关注点从'说什么'转向'让模型知道什么，以及怎么知道'。本文从范式演进的驱动力出发，分析了单次 Prompt 在复杂任务中的局限性如何催生上下文工程的需求。核心围绕三大支柱展开：RAG（检索增强生成）通过外部知识库突破模型训练数据的时效边界；记忆系统（短期、长期与工作记忆）赋予模型跨轮次的状态感知能力；工具调用（Function Calling）使模型从信息处理者升级为行动执行者。同时讨论了上下文窗口容量管理、信息密度优化与多轮对话中的注意力衰减等工程挑战，为企业级 LLM 应用的上下文架构设计提供方法论参考。")])],-1)),n[9]||(n[9]=s("h2",{id:"_1-引言",tabindex:"-1"},[a("1. 引言 "),s("a",{class:"header-anchor",href:"#_1-引言","aria-label":"Permalink to “1. 引言”"},"​")],-1)),n[10]||(n[10]=s("p",null,'如果把 Prompt Engineering 比作"学会与 LLM 对话的语法"，那么 Context Engineering 就是"学会为 LLM 准备一个认知环境"。',-1)),p(e,{type:"info"},{default:i(()=>[...n[0]||(n[0]=[a('Context Engineering 是 Prompt Engineering 的自然演进——从关注"说什么"，到关注"让模型知道什么，以及怎么知道"',-1)])]),_:1}),n[11]||(n[11]=l(`。<h2 id="_2-从-prompt-engineering-到-context-engineering-的演进" tabindex="-1">2. 从 Prompt Engineering 到 Context Engineering 的演进 <a class="header-anchor" href="#_2-从-prompt-engineering-到-context-engineering-的演进" aria-label="Permalink to “2. 从 Prompt Engineering 到 Context Engineering 的演进”">​</a></h2><p>让我们先理解为什么会出现这个演进：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Prompt Engineering 时代（2022-2023）：</span></span>
<span class="line"><span>  关注点：如何写好一段 Prompt</span></span>
<span class="line"><span>  典型工作：调教措辞、设计 Few-shot 示例、尝试 CoT</span></span>
<span class="line"><span>  假设：模型的能力是固定的，Prompt 是唯一的杠杆</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Context Engineering 时代（2024-至今）：</span></span>
<span class="line"><span>  关注点：模型在做出决策时&quot;看到了什么&quot;</span></span>
<span class="line"><span>  典型工作：上下文组装、信息检索增强、动态上下文管理</span></span>
<span class="line"><span>  假设：模型的能力 = 模型权重 × 上下文质量，两个都可以优化</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p><strong>演进的核心原因</strong>：</p><ol><li><strong>上下文窗口急剧扩大</strong>：从 GPT-3 的 2K token 到 Gemini 的 2M token，可塞入的信息量增长了 1000 倍。&quot;放什么进去&quot;变成了关键决策。</li><li><strong>RAG 模式的成熟</strong>：模型不再只靠训练时记住的知识，而是从外部动态获取信息。上下文变成了一个&quot;动态拼装的认知界面&quot;。</li><li><strong>Agent 工作流的兴起</strong>：Agent 在执行任务过程中不断积累信息（工具返回、中间结果、错误反馈），这些信息如何组织直接影响 Agent 的表现。</li></ol><p><strong>一个形象的比喻</strong>：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Prompt Engineering  = 写一封邮件（措辞、语气、结构）</span></span>
<span class="line"><span>Context Engineering = 布置一间会议室（谁在场、桌上有什么资料、墙上贴了什么便签、</span></span>
<span class="line"><span>                      窗户透进什么光、会议前发生了什么）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="_3-上下文组装策略" tabindex="-1">3. 上下文组装策略 <a class="header-anchor" href="#_3-上下文组装策略" aria-label="Permalink to “3. 上下文组装策略”">​</a></h2>`,9)),s("p",null,[n[2]||(n[2]=a("上下文组装解决的核心问题是：",-1)),p(e,{bold:"",type:"note"},{default:i(()=>[...n[1]||(n[1]=[a("在一次推理请求中，应当选择哪些信息放入上下文窗口，以及如何合理安排它们的顺序？",-1)])]),_:1})]),n[12]||(n[12]=l(`<h3 id="_3-1-典型的上下文组装结构" tabindex="-1">3.1 典型的上下文组装结构 <a class="header-anchor" href="#_3-1-典型的上下文组装结构" aria-label="Permalink to “3.1 典型的上下文组装结构”">​</a></h3><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>┌────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ 1. System Prompt          (~500 tokens)        │</span></span>
<span class="line"><span>│    角色 + 规则 + 格式要求                       │</span></span>
<span class="line"><span>├────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ 2. 持久化上下文            (~200 tokens)        │</span></span>
<span class="line"><span>│    用户偏好 / 历史关键事实 / 对话目的            │</span></span>
<span class="line"><span>├────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ 3. 检索到的参考信息        (~2000 tokens)       │</span></span>
<span class="line"><span>│    文档片段 / FAQ / 知识库条目                  │</span></span>
<span class="line"><span>├────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ 4. 工具调用历史            (~500 tokens)        │</span></span>
<span class="line"><span>│    之前调用了什么工具，返回了什么结果            │</span></span>
<span class="line"><span>├────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ 5. 对话历史                (~2000 tokens)       │</span></span>
<span class="line"><span>│    最近 N 轮对话                             │</span></span>
<span class="line"><span>├────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ 6. 用户当前输入            (~200 tokens)        │</span></span>
<span class="line"><span>│    最新一条消息                               │</span></span>
<span class="line"><span>└────────────────────────────────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br></div></div><h3 id="_3-2-组装原则" tabindex="-1">3.2 组装原则 <a class="header-anchor" href="#_3-2-组装原则" aria-label="Permalink to “3.2 组装原则”">​</a></h3><h4 id="原则一-相关性优先于完整性" tabindex="-1">原则一：相关性优先于完整性 <a class="header-anchor" href="#原则一-相关性优先于完整性" aria-label="Permalink to “原则一：相关性优先于完整性”">​</a></h4><p>不是把所有能找到的信息都塞进去。上下文窗口就像桌面的工作区——东西放得越多，越难集中注意力。</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>错误做法：找到 20 个相关的文档片段，全部放进去</span></span>
<span class="line"><span>正确做法：只放最相关的 3-5 个，其他作为备选</span></span>
<span class="line"><span></span></span>
<span class="line"><span>原因：1) 过多的不相关信息会稀释关键信号</span></span>
<span class="line"><span>     2) &quot;Lost in the Middle&quot; 现象证明，中间位置的信息最容易被模型忽略</span></span>
<span class="line"><span>     3) 每多一个 token，推理延迟和成本都在增加</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h4 id="原则二-重要信息放在两端" tabindex="-1">原则二：重要信息放在两端 <a class="header-anchor" href="#原则二-重要信息放在两端" aria-label="Permalink to “原则二：重要信息放在两端”">​</a></h4><p>研究表明，LLM 对上下文中位置信息的注意力不是均匀分布的：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>上下文窗口中的注意力分布示意：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  注意力强度</span></span>
<span class="line"><span>     ↑</span></span>
<span class="line"><span>     │  ████                                    ████</span></span>
<span class="line"><span>     │  ████                                    ████</span></span>
<span class="line"><span>     │  ████                                    ████</span></span>
<span class="line"><span>     │  ████                                    ████</span></span>
<span class="line"><span>     │  ████     ██                             ████</span></span>
<span class="line"><span>     │  ████     ██                      ██     ████</span></span>
<span class="line"><span>     │  ████     ██            ██        ██     ████</span></span>
<span class="line"><span>     │  ████ ██  ██   ██   ██ ██    ██  ██  ██ ████</span></span>
<span class="line"><span>     └──┴───┴───┴────┴────┴───┴─────┴───┴───┴──┴─────→ 位置</span></span>
<span class="line"><span>       开头         中间区域（注意力最低）          结尾</span></span>
<span class="line"><span></span></span>
<span class="line"><span>→ &quot;Lost in the Middle&quot;: 中间位置的信息最容易被模型忽视</span></span>
<span class="line"><span>→ 把关键指令放在开头（System Prompt）或结尾（近期对话）</span></span>
<span class="line"><span>→ 参考资料放在开头（紧接 System Prompt 后），比放在中间效果更好</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br></div></div><h4 id="原则三-结构化优于自然语言" tabindex="-1">原则三：结构化优于自然语言 <a class="header-anchor" href="#原则三-结构化优于自然语言" aria-label="Permalink to “原则三：结构化优于自然语言”">​</a></h4><p>同样的信息，用结构化的方式呈现比用自然语言描述更容易被模型准确理解：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>自然语言（差）：</span></span>
<span class="line"><span>&quot;我们的产品有三种订阅计划，基础版每月 29 元包含 100 次调用和基本支持，</span></span>
<span class="line"><span> 专业版每月 99 元包含 1000 次调用和优先支持还有自定义模型，</span></span>
<span class="line"><span> 企业版需要联系销售包含无限调用和专属支持...&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>结构化（好）：</span></span>
<span class="line"><span>| 计划   | 月费   | API 调用数 | 支持级别 | 自定义模型 |</span></span>
<span class="line"><span>|--------|--------|-----------|---------|-----------|</span></span>
<span class="line"><span>| 基础版 | ¥29   | 100       | 基本    | 无        |</span></span>
<span class="line"><span>| 专业版 | ¥99   | 1,000     | 优先    | 有        |</span></span>
<span class="line"><span>| 企业版 | 联系销售 | 无限     | 专属    | 有        |</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><h2 id="_4-上下文压缩与缓存" tabindex="-1">4. 上下文压缩与缓存 <a class="header-anchor" href="#_4-上下文压缩与缓存" aria-label="Permalink to “4. 上下文压缩与缓存”">​</a></h2><h3 id="_4-1-上下文压缩" tabindex="-1">4.1 上下文压缩 <a class="header-anchor" href="#_4-1-上下文压缩" aria-label="Permalink to “4.1 上下文压缩”">​</a></h3><p>随着对话进行，上下文持续增长。如果不加处理，最终会超出窗口限制或导致推理成本爆炸。上下文压缩解决的就是这个问题。</p><p><strong>策略一：滑动窗口（Sliding Window）</strong></p><p>最简单的方式：只保留最近的 N 轮对话，丢弃更早的。</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>完整对话历史: [R1, R2, R3, ..., R45, R46, R47, R48, R49, R50]</span></span>
<span class="line"><span>滑动窗口 N=10:                              [R41 ... R50]  ← 只保留最近 10 轮</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>缺点：丢失了用户早期表达的重要偏好和上下文线索。</p><p><strong>策略二：摘要压缩（Summarization）</strong></p><p>用 LLM 对早期对话进行渐进式摘要：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>持久化摘要（随时间更新）：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>阶段 1:  [R1-R5 原始对话]</span></span>
<span class="line"><span>阶段 2:  [摘要(R1-R5)] + [R6-R10 原始对话]</span></span>
<span class="line"><span>阶段 3:  [摘要(摘要(R1-R5) + R6-R10)] + [R11-R15 原始对话]</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>最终上下文：</span></span>
<span class="line"><span>┌──────────────────────────────────────┐</span></span>
<span class="line"><span>│ 对话摘要（2-3 句，覆盖全部历史关键信息） │</span></span>
<span class="line"><span>├──────────────────────────────────────┤</span></span>
<span class="line"><span>│ 最近 10 轮原始对话                    │</span></span>
<span class="line"><span>├──────────────────────────────────────┤</span></span>
<span class="line"><span>│ 用户当前输入                         │</span></span>
<span class="line"><span>└──────────────────────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><p><strong>策略三：关键词提取（Keyword Extraction）</strong></p><p>从历史对话中提取关键实体和偏好，存入一个精简的记忆字典：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>记忆字典：</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  &quot;user_name&quot;: &quot;小明&quot;,</span></span>
<span class="line"><span>  &quot;preferred_language&quot;: &quot;中文&quot;,</span></span>
<span class="line"><span>  &quot;expertise_level&quot;: &quot;高级 Python 开发者&quot;,</span></span>
<span class="line"><span>  &quot;current_project&quot;: &quot;构建 RAG 系统&quot;,</span></span>
<span class="line"><span>  &quot;key_decisions&quot;: [&quot;使用 ChromaDB&quot;, &quot;嵌入模型选 BGE-large&quot;],</span></span>
<span class="line"><span>  &quot;open_questions&quot;: [&quot;如何处理多轮对话的上下文压缩&quot;]</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>这种方式的内存开销极小（通常 100-300 tokens），适合长期跨会话记忆。</p><h3 id="_4-2-上下文缓存" tabindex="-1">4.2 上下文缓存 <a class="header-anchor" href="#_4-2-上下文缓存" aria-label="Permalink to “4.2 上下文缓存”">​</a></h3><p>对于多轮对话或批量请求场景，上下文中有一部分是不变的（如 System Prompt）：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请求 1: [System Prompt] + [User Msg 1]</span></span>
<span class="line"><span>请求 2: [System Prompt] + [User Msg 2]  ← System Prompt 的 KV Cache 可以复用！</span></span>
<span class="line"><span>请求 3: [System Prompt] + [User Msg 3]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>优化：</span></span>
<span class="line"><span>  首次请求 → 计算 System Prompt 的 KV Cache 并缓存</span></span>
<span class="line"><span>  后续请求 → 直接从缓存读取，跳过 Prefill 阶段中的 System Prompt 部分</span></span>
<span class="line"><span>  → TTFT 降低 30-50%（取决于 System Prompt 在总输入中的占比）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p><strong>Anthropic 的 Prompt Caching</strong> 和 <strong>Google Gemini 的 Context Caching</strong> 都提供了这一功能的 API 支持。开发者可以标记上下文中的哪些部分是可缓存的，API 会自动处理缓存命中和失效。</p><h2 id="_5-动态上下文管理" tabindex="-1">5. 动态上下文管理 <a class="header-anchor" href="#_5-动态上下文管理" aria-label="Permalink to “5. 动态上下文管理”">​</a></h2>`,31)),s("p",null,[n[4]||(n[4]=a("最先进的 Context Engineering 实践是",-1)),n[5]||(n[5]=s("strong",null,"动态上下文管理",-1)),n[6]||(n[6]=a("：",-1)),p(e,{type:"note"},{default:i(()=>[...n[3]||(n[3]=[a('不是一次性地静态组装上下文，而是让 Agent 在执行过程中根据当前需求主动"拉取"所需上下文。',-1)])]),_:1})]),n[13]||(n[13]=l(`<h3 id="_5-1-按需检索-lazy-retrieval" tabindex="-1">5.1 按需检索（Lazy Retrieval） <a class="header-anchor" href="#_5-1-按需检索-lazy-retrieval" aria-label="Permalink to “5.1 按需检索（Lazy Retrieval）”">​</a></h3><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>静态 RAG（传统）：</span></span>
<span class="line"><span>  用户提问 → 一次性检索所有相关文档 → 全部放入上下文 → 生成回答</span></span>
<span class="line"><span>  问题：可能检索了 15 个文档片段，但回答只需要其中 3 个</span></span>
<span class="line"><span></span></span>
<span class="line"><span>动态 RAG（按需）：</span></span>
<span class="line"><span>  用户提问 → 初步检索 3 个文档 → 生成初步回答</span></span>
<span class="line"><span>    → 发现需要更多细节 → 根据中间推理结果二次检索</span></span>
<span class="line"><span>    → 补充 2 个针对性文档 → 完善回答</span></span>
<span class="line"><span>  优势：上下文更精准，不被无关信息稀释</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h3 id="_5-2-上下文窗口的-信息预算-管理" tabindex="-1">5.2 上下文窗口的&quot;信息预算&quot;管理 <a class="header-anchor" href="#_5-2-上下文窗口的-信息预算-管理" aria-label="Permalink to “5.2 上下文窗口的&quot;信息预算&quot;管理”">​</a></h3><p>把上下文窗口视为一种有限资源（信息预算），需要做预算分配：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>128K 上下文窗口的预算分配示例：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  知识检索:  ████████████████░░░░░░  60K (高优先级)</span></span>
<span class="line"><span>  对话历史:  ██████████░░░░░░░░░░░░  40K</span></span>
<span class="line"><span>  Agent 状态: ████░░░░░░░░░░░░░░░░░░ 16K</span></span>
<span class="line"><span>  工具历史:   ██░░░░░░░░░░░░░░░░░░░░  8K</span></span>
<span class="line"><span>  预留空间:   ░░░░░░░░░░░░░░░░░░░░░░  4K (应对突发需求)</span></span>
<span class="line"><span>             └───────────────────────┘</span></span>
<span class="line"><span>                    128K 总额</span></span>
<span class="line"><span></span></span>
<span class="line"><span>当预算紧张时：</span></span>
<span class="line"><span>  1. 先压缩对话历史（摘要代替原文）</span></span>
<span class="line"><span>  2. 降低检索结果数（只保留 Top 3 而非 Top 10）</span></span>
<span class="line"><span>  3. 精简工具调用历史（只保留最后一次调用的关键结果）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><h3 id="_5-3-上下文污染防控" tabindex="-1">5.3 上下文污染防控 <a class="header-anchor" href="#_5-3-上下文污染防控" aria-label="Permalink to “5.3 上下文污染防控”">​</a></h3><p>动态上下文管理还需要考虑<strong>上下文污染</strong>问题——错误或误导性信息一旦进入上下文，可能在整个 Agent 执行链条中传播：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>污染传播示例：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  错误的工具返回 → 进入上下文</span></span>
<span class="line"><span>    → 模型基于错误信息做推理 → 生成错误结论</span></span>
<span class="line"><span>    → 错误结论保留在上下文中 → 影响后续所有决策</span></span>
<span class="line"><span></span></span>
<span class="line"><span>防控手段：</span></span>
<span class="line"><span>  - 对进入上下文的外部信息标注来源和置信度</span></span>
<span class="line"><span>  - 定期让模型&quot;反思&quot;当前上下文中的假设是否仍然成立</span></span>
<span class="line"><span>  - 对关键决策点，要求模型引用上下文中的具体证据</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><h2 id="_6-总结" tabindex="-1">6. 总结 <a class="header-anchor" href="#_6-总结" aria-label="Permalink to “6. 总结”">​</a></h2><p>Context Engineering 的核心洞察是 LLM 的输出质量不止取决于模型本身有多强，还取决于它在做决策时&quot;看到的世界&quot;是什么样子。精心管理的上下文，可以让一个中等模型产生超越更大模型的效果；而混乱的上下文，可以让最强模型也犯低级错误。</p>`,10))]))}});export{h as __pageData,k as default};
